package com.icao.wechatauth

import android.content.Context
import android.content.pm.PackageManager
import com.tencent.mm.opensdk.modelbase.BaseResp
import com.tencent.mm.opensdk.modelmsg.SendAuth
import com.tencent.mm.opensdk.openapi.IWXAPI
import com.tencent.mm.opensdk.openapi.WXAPIFactory
import expo.modules.kotlin.Promise
import expo.modules.kotlin.modules.Module
import expo.modules.kotlin.modules.ModuleDefinition

private const val APP_ID_METADATA_KEY = "com.icao.wechatauth.APP_ID"

/**
 * Process-wide response coordinator used by the package-specific WXEntryActivity generated by the
 * Expo config plugin. It owns exactly one authorization request and validates the echoed state
 * before resolving JavaScript. No access token or AppSecret is ever present in the client.
 */
object IcaoWechatAuthCoordinator {
  private data class PendingAuthorization(val state: String, val promise: Promise)

  private var pending: PendingAuthorization? = null

  @Synchronized
  fun authorize(context: Context, state: String, promise: Promise) {
    if (state.isBlank()) {
      promise.reject("invalid_wechat_auth_state", "WeChat authorization state is required", null)
      return
    }
    val api = api(context)
    if (api == null) {
      promise.reject(
        "wechat_auth_configuration_pending",
        "WeChat login is waiting for platform configuration",
        null
      )
      return
    }
    if (!api.isWXAppInstalled || api.wxAppSupportAPI <= 0) {
      promise.reject(
        "wechat_app_not_installed",
        "WeChat is not installed or does not support authorization",
        null
      )
      return
    }
    if (pending != null) {
      promise.reject("wechat_auth_in_progress", "A WeChat authorization request is already active", null)
      return
    }

    pending = PendingAuthorization(state, promise)
    val request = SendAuth.Req().apply {
      scope = "snsapi_userinfo"
      this.state = state
    }
    if (!api.sendReq(request)) {
      pending = null
      promise.reject("wechat_auth_unavailable", "WeChat authorization could not be started", null)
    }
  }

  fun status(context: Context): Map<String, Boolean> {
    val api = api(context)
    return mapOf(
      "configured" to (api != null),
      "installed" to (api?.isWXAppInstalled == true),
      "supported" to ((api?.wxAppSupportAPI ?: 0) > 0)
    )
  }

  fun api(context: Context): IWXAPI? {
    val appId = appId(context) ?: return null
    return WXAPIFactory.createWXAPI(context.applicationContext, appId, true).also {
      it.registerApp(appId)
    }
  }

  @Synchronized
  fun handleResponse(response: BaseResp) {
    val authorization = response as? SendAuth.Resp ?: return
    val active = pending ?: return
    pending = null

    if (authorization.state != active.state) {
      active.promise.reject(
        "invalid_wechat_auth_response",
        "WeChat returned a mismatched authorization state",
        null
      )
      return
    }
    when (authorization.errCode) {
      BaseResp.ErrCode.ERR_OK -> {
        val code = authorization.code
        if (code.isNullOrBlank()) {
          active.promise.reject("wechat_auth_failed", "WeChat returned no authorization code", null)
        } else {
          active.promise.resolve(mapOf("code" to code, "state" to active.state))
        }
      }
      BaseResp.ErrCode.ERR_USER_CANCEL -> active.promise.reject(
        "social_auth_cancelled",
        "WeChat authorization was cancelled",
        null
      )
      else -> active.promise.reject("wechat_auth_failed", "WeChat authorization failed", null)
    }
  }

  @Synchronized
  fun cancelPending() {
    val active = pending ?: return
    pending = null
    active.promise.reject("social_auth_cancelled", "WeChat authorization was cancelled", null)
  }

  private fun appId(context: Context): String? {
    val applicationInfo = context.packageManager.getApplicationInfo(
      context.packageName,
      PackageManager.GET_META_DATA
    )
    return applicationInfo.metaData?.getString(APP_ID_METADATA_KEY)?.trim()?.takeIf { it.isNotEmpty() }
  }
}

class IcaoWechatAuthModule : Module() {
  override fun definition() = ModuleDefinition {
    Name("IcaoWechatAuth")

    Function("getStatus") {
      val context = appContext.reactContext
      if (context == null) {
        mapOf("configured" to false, "installed" to false, "supported" to false)
      } else {
        IcaoWechatAuthCoordinator.status(context)
      }
    }

    AsyncFunction("authorize") { state: String, promise: Promise ->
      val context = appContext.reactContext
      if (context == null) {
        promise.reject("wechat_auth_unavailable", "React context is unavailable", null)
      } else {
        IcaoWechatAuthCoordinator.authorize(context, state, promise)
      }
    }

    OnActivityDestroys {
      IcaoWechatAuthCoordinator.cancelPending()
    }
  }
}
